// The contract comes from libs/shared via functionGlobalContext
// (infra/nodered/data/settings.js; docker-compose mounts /contract read-only).
// Ranges and types are deliberately not here - the next node validates them
// against the generated telemetry.schema.json.
const contract = global.get('contract');
const schema = global.get('telemetrySchema');
if (!contract || !schema) {
    node.error('contract missing from global context - is /contract mounted?', msg);
    return null;
}

const parts = String(msg.topic).split('/');
const sensorKey =
    parts.length === 3 &&
    parts[0] === contract.node.topicPrefix &&
    parts[2] === contract.node.topicSuffix
        ? parts[1]
        : null;

if (sensorKey === null || !new RegExp(contract.sensorKeyPattern).test(sensorKey)) {
    msg.reason = `[${msg.topic}] topic does not match ${contract.node.telemetryFilter} with a valid sensor key (${contract.sensorKeyPattern})`;
    return [null, msg];
}

// Keep the bytes that arrived and validate a parsed copy, so the gateway
// forwards telemetry exactly as the node sent it.
msg.sensorKey = sensorKey;
msg.raw = msg.payload;
msg.schema = schema;
return [msg, null];

// Only the topic changes here: the gateway publishes under its own identity,
// the body is the untouched string the node sent.
const contract = global.get('contract');
const gatewayId = env.get('GATEWAY_ID');
if (!gatewayId) {
    node.error('GATEWAY_ID is not set - the gateway has not been paired yet', msg);
    return null;
}

msg.topic = contract.cloud.telemetryTopic
    .replace('{gatewayId}', gatewayId)
    .replace('{sensorKey}', msg.sensorKey);
msg.payload = msg.raw;
return msg;

// Two kinds of failure arrive here from the `json` node: invalid JSON and a
// body that failed the schema. msg.error.message already carries the ajv
// errorsText; msg.schemaError holds the structured detail for schema failures.
const detail = (msg.error && msg.error.message) || 'unknown error';
const raw = typeof msg.raw === 'string' ? msg.raw : JSON.stringify(msg.payload);
msg.reason = `[${msg.topic}] ${detail} :: ${String(raw).slice(0, 160)}`;
return msg;
